const SHELL='treino-shell-v1',MEDIA='treino-media-v1';const files=['./','index.html','style.css','app.js','core.js','exercises.json','manifest.webmanifest','icon-192.png','icon-512.png','CREDITOS.md'];self.addEventListener('install',e=>e.waitUntil(caches.open(SHELL).then(c=>c.addAll(files))));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;e.respondWith((async()=>{const cached=await caches.match(e.request);if(cached){const range=e.request.headers.get('range');if(range&&new URL(e.request.url).pathname.endsWith('.mp4')){const data=await cached.arrayBuffer();const m=/bytes=(\d+)-(\d*)/.exec(range);if(m){const start=Number(m[1]),end=m[2]?Math.min(Number(m[2]),data.byteLength-1):data.byteLength-1;if(start>=data.byteLength)return new Response(null,{status:416,headers:{'Content-Range':'bytes */'+data.byteLength}});return new Response(data.slice(start,end+1),{status:206,headers:{'Content-Type':'video/mp4','Content-Length':String(end-start+1),'Accept-Ranges':'bytes','Content-Range':`bytes ${start}-${end}/${data.byteLength}`}})}}return cached;}try{return await fetch(e.request)}catch(err){if(e.request.mode==='navigate')return caches.match(new URL('index.html',self.registration.scope));throw err}})())});
